-- One-line description of each course, shown on its module card in practice by module.
-- Generated by scripts/generate-submodule-seed-sql.ts. Data only: fills the description of every domain row of a course
-- that has none yet, so a description the admin has written is never overwritten. Safe to re-run.
-- Edit later in Admin > Domains > (domain) > Submodules > Description.

with d(title, description) as (values
  ($q$Claude Platform & Model Foundations$q$, $q$Which entry point, features, model and amount of context to use in a Claude session.$q$),
  ($q$Prompting & Task Execution$q$, $q$A reusable structure for writing prompts that get clear, usable results.$q$),
  ($q$Evaluating & Validating Claude's Output$q$, $q$How to check Claude's answers for accuracy before you rely on them in your own work.$q$),
  ($q$Workflow Integration & Solution Design$q$, $q$Deciding which workflow steps go to Claude and which stay with people.$q$),
  ($q$Configuration & Knowledge Management$q$, $q$Setting up Claude's context and instructions once so later conversations start well-informed.$q$),
  ($q$Governance, Risk & Responsible Use$q$, $q$Deciding which uses of Claude are appropriate and low-risk.$q$),
  ($q$Troubleshooting & Optimization$q$, $q$Working out why a response disappoints and what to change.$q$),
  ($q$MSO Foundations$q$, $q$Core model and technical concepts that the later Developer courses depend on.$q$),
  ($q$Production-Grade Prompting, Agents & Tool Use$q$, $q$Writing dependable prompts, wiring up tools and managing context in a first real Claude integration.$q$),
  ($q$Claude Code, MCP & Integration$q$, $q$Configuring and sharing a Claude integration, and connecting it safely to live systems.$q$),
  ($q$Production Engineering, Evals & Security$q$, $q$Testing an agent under real-world load, and checking its quality and security.$q$),
  ($q$Accelerators & IP Contribution$q$, $q$Getting a finished build ready to be reused, reviewed and deployed elsewhere.$q$)
)
update quiz_submodules sm
set description = d.description
from d
where sm.title = d.title and (sm.description is null or btrim(sm.description) = '');

-- Check: every module should show a description
select m.track, sm.title as module, left(coalesce(sm.description, ''), 60) as description_start
from quiz_submodules sm
join quiz_modules m on m.id = sm.module_id
group by m.track, sm.title, sm.description
order by m.track, sm.title;
